komut.debian:
sudo -n systemctl restart {servis} || exit $?
echo "servis="{servis}
echo "durum=$(systemctl is-active {servis})"

komut.rhel:
sudo -n systemctl restart {servis} || exit $?
echo "servis="{servis}
echo "durum=$(systemctl is-active {servis})"

komut.alpine:
sudo -n rc-service {servis} restart >/dev/null || exit $?
echo "servis="{servis}
if rc-service {servis} status >/dev/null 2>&1; then echo durum=active; else echo durum=inactive; fi
